{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.horizontal_sales_categories AS ( with metafields AS ( SELECT upper(trim(sku_group)) as sku_group ,product_type,product_tags from snitch_db.maplemonk.metafields_data ), price as ( SELECT upper(trim(VARIANT.value:sku::STRING)) as sku, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku)) as sku, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price ), final_price_adj as ( select upper(trim(sku)) as sku, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), final_price as ( select upper(trim(sku)) as sku, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), cost_price as ( select upper(trim(sku)) as sku, cost_price from snitch_db.maplemonk.sku_cost_price ), category as ( select upper(trim(sku_group)) as sku_group, category from snitch_db.maplemonk.availability_master_v2 ), shopify_sales AS ( SELECT order_timestamp::date AS Date, \'Shopify\' AS type, upper(trim(a.sku_group)) as sku_group, e.category as category, b.product_tags as product_tags, c.original_price as price, d.cost_price, case when lower(webshopney) = \'snitch_ios\' and lower(tags) = \'snitch_ios\' then \'App2_IOS\' when lower(webshopney) = \'snitch_ios\' and lower(tags) != \'snitch_ios\' then \'App2_Android\' when lower(webshopney) = \'web\' then \'Web\' else \'App\' end as channel, SUM(NULLIF(gross_sales, 0)) AS gross_sales, SUM(NULLIF(quantity, 0)) AS gross_quantity, SUM( CASE WHEN lower(trim(payment_channel)) = \'cod\' and lower(discount_code) not like \'%snitch_rms%\' THEN (quantity)*(c.original_price) - (gross_sales-100) when lower(discount_code) not like \'%snitch_rms%\' then (quantity)*(c.original_price) - (gross_sales) else ((quantity)*(c.original_price) - coupon_discount - gross_sales) END ) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN gross_sales ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN gross_sales ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.fact_items_snitch a LEFT JOIN metafields b ON a.sku_group = b.sku_group LEFT JOIN final_price c ON a.sku = c.sku left join cost_price d on a.sku = d.sku left join category e on upper(trim(a.sku_group)) = e.sku_group WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), marketplace_data AS ( SELECT a.order_date AS Date, \'Marketplace\' AS type, upper(trim(a.sku_group)) as sku_group, e.category as category, c.product_tags as product_tags, b.original_price as price, d.cost_price, marketplace_mapped as channel, SUM(NULLIF(a.selling_price, 0)) AS gross_sales, SUM(NULLIF(a.shipping_quantity, 0)) AS gross_quantity, SUM(NULLIF((b.original_price * a.shipping_quantity) - a.selling_price, 0)) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.unicommerce_fact_items_snitch a left join final_price b on upper(trim(a.sku)) = b.sku left join metafields c on a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku left join category e on upper(trim(a.sku_group)) = e.sku_group where marketplace_mapped IN (\'Myntra\',\'SNAPMINT\',\'CRED\',\'DONOSHOP\',\'FYND\',\'AMAZON\',\'MYNTRA\',\'MENSXP\',\'NYKAA_FASHION\',\'AJIO\',\'FLIPKART\') GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), stores_data AS ( SELECT order_date AS Date, \'Store\' AS type, upper(trim(a.sku_group)) as sku_group, e.category as category, b.product_tags as product_tags, c.original_price as price, d.cost_price, MARKETPLACE_MAPPED AS channel, SUM(NULLIF(selling_price, 0)) AS gross_sales, SUM(NULLIF(shipping_quantity, 0)) AS gross_quantity, sum(shipping_quantity*c.original_price - selling_price) as discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN phone ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.STORE_fact_items_offline a left join metafields b on a.sku_group = b.sku_group LEFT JOIN final_price c ON a.sku = c.sku left join cost_price d on a.sku = d.sku left join category e on upper(trim(a.sku_group)) = e.sku_group where marketplace_mapped not like \'%WH%\' and lower(a.sku_group) not like \'cb%\' GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ) select * from shopify_sales union all select * from marketplace_data union all select * from stores_data );",
